insert into public.follows select a.id, b.id from public.profiles a, public.profiles b where a.id<>b.id and a.id::text like '00000000-0000-4000-8000%' and b.id::text like '00000000-0000-4000-8000%' on conflict do nothing;
insert into public.reactions select u.id, p.id from public.profiles u, public.projects p where u.id::text like '00000000-0000-4000-8000%' and p.id::text like '10000000%' and p.owner_id<>u.id on conflict do nothing;
